INSERT INTO "public"."viewing_spots" ("id", "name", "slug", "lat", "lng", "region", "description", "parking_info", "terrain_notes", "has_services", "cell_coverage", "totality_duration_seconds", "totality_start", "sun_altitude", "sun_azimuth", "spot_type", "trail_distance_km", "trail_time_minutes", "difficulty", "elevation_gain_m", "trailhead_lat", "trailhead_lng", "photos", "horizon_check", "warnings", "nearby_poi", "observer_height_above_ground") VALUES ('blue-lagoon', 'Blue Lagoon', 'blue-lagoon', 63.88, -22.449, 'reykjanes', 'Iceland''s most famous tourist attraction — a geothermal spa set in a black lava field on the Reykjanes Peninsula. For the first time in its operating history, the Blue Lagoon falls directly in the path of totality. Watching the sky darken during totality while soaking in the milky-blue 38°C water with geothermal steam rising around you would be an utterly unique eclipse experience. The flat volcanic terrain provides a clear horizon in all directions. Check the Blue Lagoon website for eclipse-day operations and any special packages closer to the date.', 'Large professional parking facilities with capacity for hundreds of cars. Well-organized arrival/departure system.', 'Flat volcanic lava field at approximately 30m elevation. No significant terrain nearby. Open sky in all directions.', true, 'good', 96, '2026-08-12 17:49:05+00', 24.7, 252.4, 'drive-up', null, null, null, null, null, null, '[{"alt":"Milky-blue geothermal waters at Blue Lagoon, Reykjanes peninsula","credit":"Unsplash / Jacob Vizek","is_hero":true,"license":"unsplash","filename":"blue-lagoon-hero.webp","horizon_view":false}]', '{"sweep":[{"azimuth":205,"distance_m":150,"horizon_angle":0.6398290871495367},{"azimuth":206,"distance_m":150,"horizon_angle":0.6401197733916516},{"azimuth":207,"distance_m":150,"horizon_angle":0.6402563454980098},{"azimuth":208,"distance_m":150,"horizon_angle":0.6387983727597194},{"azimuth":209,"distance_m":150,"horizon_angle":0.6298353299426702},{"azim