-- hellnar-viewpoint
INSERT INTO "public"."viewing_spots" ("id", "name", "slug", "lat", "lng", "region", "description", "parking_info", "terrain_notes", "has_services", "cell_coverage", "totality_duration_seconds", "totality_start", "sun_altitude", "sun_azimuth", "spot_type", "trail_distance_km", "trail_time_minutes", "difficulty", "elevation_gain_m", "trailhead_lat", "trailhead_lng", "photos", "horizon_check", "warnings", "nearby_poi", "observer_height_above_ground") VALUES ('hellnar-viewpoint', 'Hellnar Coastal Viewpoint', 'hellnar-viewpoint', 64.757, -23.648, 'snaefellsnes', 'A historic fishing village on the southern coast of the Snæfellsnes Peninsula, connected to Arnarstapi by a famous 2.5 km coastal walking path (the Gatklettur sea arch lies along the path closer to the Arnarstapi end). Hellnar features dramatic basalt sea caves and nesting seabird colonies. The Fjöruhúsið café, set in a converted fish house overlooking a small cove, is considered one of the most charming cafés in Iceland. The south-facing coast provides a clear horizon to the west-southwest for eclipse viewing.', 'Small parking lot at the end of the road in Hellnar. Approximately 15 cars. Additional parking at Arnarstapi (2.5km walk along the coastal path).', 'Coastal village at sea level. South-facing shore with views SW/W over the Atlantic. Walking paths through lava fields to sea caves and arch.', true, 'limited', 119, '2026-08-12 17:46:10+00', 25.1, 250.5, 'drive-up', null, null, null, null, null, null, '[{"alt":"Hellnakirkja (The church at Hellnar) on the Snæfellsnes peninsula in Iceland. ","credit":"Unsplash / Sigurdur Fjalar Jonsson","is_hero":true,"license":"unsplash","filename":"hellnar-viewpoint-hero.webp","horizon_view":true}]', '{"sweep":[{"azimuth":205,"distance_m":32000,"horizon_angle":0},{"azimuth":206,"distance_m":32000,"horizon_angle":0},{"azimuth":207,"distance_m":32000,"horizon_angle":0},{"azimuth":208,"distance_m":32000,"horizon_angle":0},{"azimuth":209,"distance_m":32000,"horizon_angle":0},{