-- londrangar-malarrif
INSERT INTO "public"."viewing_spots" ("id", "name", "slug", "lat", "lng", "region", "description", "parking_info", "terrain_notes", "has_services", "cell_coverage", "totality_duration_seconds", "totality_start", "sun_altitude", "sun_azimuth", "spot_type", "trail_distance_km", "trail_time_minutes", "difficulty", "elevation_gain_m", "trailhead_lat", "trailhead_lng", "photos", "horizon_check", "warnings", "nearby_poi", "observer_height_above_ground") VALUES ('londrangar-malarrif', 'Lóndrangar Cliffs / Malarrif', 'londrangar-malarrif', 64.734, -23.776, 'snaefellsnes', 'Two dramatic basalt sea pillars — the taller rising 75 meters and the shorter 61 meters — standing like sentinels off the southwest coast of the Snæfellsnes Peninsula. These volcanic plugs are the remains of an ancient crater eroded by the Atlantic over millennia. The nearby Malarrif visitor center and lighthouse complete the scene. The south-west facing coastline provides an excellent open horizon toward the eclipse sun. An eclipse with the Lóndrangar silhouette would produce one of the most iconic photographs of the event.', 'Lóndrangar viewpoint parking (~20 cars) and separate Malarrif visitor center parking (~20 cars). Both are short walks from the cliffs.', 'Coastal cliff path. SW-facing, open Atlantic. Low lava field terrain inland. Walking paths are well-maintained.', true, 'limited', 121, '2026-08-12 17:46:05+00', 25.2, 250.3, 'drive-up', null, null, null, null, null, null, '[{"alt":"Londrangar basalt sea stacks on the southern Snaefellsnes coast","credit":"EclipseChase.is / Martin Herchl","is_hero":true,"license":"© Martin Herchl — All rights reserved","filename":"londrangar-malarrif-hero.webp","horizon_view":true}]', '{"sweep":[{"azimuth":205,"distance_m":5500,"horizon_angle":0},{"azimuth":206,"distance_m":5500,"horizon_angle":0},{"azimuth":207,"distance_m":5500,"horizon_angle":0},{"azimuth":208,"distance_m":5500,"horizon_angle":0},{"azimuth":209,"distance_m":5500,"horizon_angle":0},{"azimuth":2