-- ondverdarnes-svortuloft
INSERT INTO "public"."viewing_spots" ("id", "name", "slug", "lat", "lng", "region", "description", "parking_info", "terrain_notes", "has_services", "cell_coverage", "totality_duration_seconds", "totality_start", "sun_altitude", "sun_azimuth", "spot_type", "trail_distance_km", "trail_time_minutes", "difficulty", "elevation_gain_m", "trailhead_lat", "trailhead_lng", "photos", "horizon_check", "warnings", "nearby_poi", "observer_height_above_ground") VALUES ('ondverdarnes-svortuloft', 'Öndverðarnes / Svörtuloft Lighthouse', 'ondverdarnes-svortuloft', 64.878, -24.041, 'snaefellsnes', 'The westernmost point of the Snæfellsnes Peninsula — a dramatic clifftop plateau where the black basalt Svörtuloft sea cliffs plunge into the Atlantic. The small orange Skálasnagaviti lighthouse stands at the edge of the world with nothing between it and Greenland. Offers near-maximum totality for Snæfellsnes with a completely unobstructed ocean horizon in every seaward direction. Often described by visitors as "the end of the world" — an extraordinarily atmospheric place to witness the eclipse.', 'End of a bumpy gravel road (15 min from Hellissandur). Small parking area for approximately 10 cars. No overflow. Arrive early on eclipse day.', 'Flat clifftop plateau. Open Atlantic to W/NW/SW. Dramatic black sea cliffs. Extremely wind-exposed — this is one of the windiest places in Iceland.', false, 'none', 130, '2026-08-12 17:45:40+00', 25.3, 250, 'drive-up', null, null, null, null, null, null, '[{"alt":"Svortuloft lighthouse at Ondverdarnes, Snaefellsnes","credit":"Christopher Balogh / Shutterstock","is_hero":true,"license":"Shutterstock (Standard License)","filename":"ondverdarnes-svortuloft-hero.webp","horizon_view":true}]', '{"sweep":[{"azimuth":205,"distance_m":200,"horizon_angle":1.9776946242363564},{"azimuth":206,"distance_m":200,"horizon_angle":1.9842799533758553},{"azimuth":207,"distance_m":200,"horizon_angle":1.9796926769306713},{"azimuth":208,"distance_m":200,"horizon_angle":1.9556