-- perlan-reykjavik
INSERT INTO "public"."viewing_spots" ("id", "name", "slug", "lat", "lng", "region", "description", "parking_info", "terrain_notes", "has_services", "cell_coverage", "totality_duration_seconds", "totality_start", "sun_altitude", "sun_azimuth", "spot_type", "trail_distance_km", "trail_time_minutes", "difficulty", "elevation_gain_m", "trailhead_lat", "trailhead_lng", "photos", "horizon_check", "warnings", "nearby_poi", "observer_height_above_ground") VALUES ('perlan-reykjavik', 'Perlan Observation Deck', 'perlan-reykjavik', 64.129, -21.918, 'reykjavik', 'Reykjavík''s iconic glass-domed landmark, perched on Öskjuhlíð hill above the city. The 360° observation deck offers unobstructed panoramic views — west over Faxaflói bay toward the eclipse sun, north to Esja mountain, and across the entire city. The elevated position (approximately 25 m above the surrounding terrain) ensures clear sightlines even in an urban setting. The Wonders of Iceland museum inside Perlan adds educational value to the eclipse visit. For visitors staying in Reykjavík who don''t want to drive, this is the premium in-city eclipse viewing spot.', 'Öskjuhlíð hill parking area with capacity for approximately 100 cars. Also accessible by city bus and walking/cycling paths through the Öskjuhlíð forest.', 'Elevated hilltop position (~60m ASL). Glass observation deck with 360° views. Completely unobstructed western horizon over the ocean. Urban setting but elevated above rooftops.', true, 'good', 56, '2026-08-12 17:48:12+00', 24.5, 252.8, 'drive-up', null, null, null, null, null, null, '[{"alt":"View from Perlan observation deck and dome above Reykjavik skyline","credit":"Unsplash / Hendrik Alting","is_hero":true,"license":"unsplash","filename":"perlan-reykjavik-hero.webp","horizon_view":true}]', '{"sweep":[{"azimuth":205,"distance_m":31000,"horizon_angle":0.23154535912758098},{"azimuth":206,"distance_m":25000,"horizon_angle":0.17411009216983622},{"azimuth":207,"distance_m":25000,"horizon_angle":0.27340774