INSERT INTO "public"."viewing_spots" ("id", "name", "slug", "lat", "lng", "region", "description", "parking_info", "terrain_notes", "has_services", "cell_coverage", "totality_duration_seconds", "totality_start", "sun_altitude", "sun_azimuth", "spot_type", "trail_distance_km", "trail_time_minutes", "difficulty", "elevation_gain_m", "trailhead_lat", "trailhead_lng", "photos", "horizon_check", "warnings", "nearby_poi", "observer_height_above_ground") VALUES ('sky-lagoon', 'Sky Lagoon', 'sky-lagoon', 64.113, -21.996, 'reykjavik', 'A modern geothermal infinity pool on the southern edge of the Reykjavík metropolitan area (Kársnes peninsula, Kópavogur), specifically designed with an ocean-facing infinity edge overlooking Faxaflói bay to the southwest. The design literally frames the eclipse sun''s bearing — the exact direction it sits at totality. Watching the sky darken and the corona appear while soaking in a geothermal pool with the Atlantic stretching to the horizon would be a uniquely Icelandic eclipse experience.', 'Professional parking facility at Sky Lagoon. Sufficient capacity. Also accessible by public bus from downtown Reykjavík.', 'Oceanfront facility at sea level. Infinity pool edge faces directly west over Faxaflói bay. Completely unobstructed western horizon.', true, 'good', 63, '2026-08-12 17:48:15+00', 24.5, 252.7, 'drive-up', null, null, null, null, null, null, '[{"alt":"Sky Lagoon geothermal infinity pool","credit":"Shutterstock / Irena W","is_hero":true,"license":"Shutterstock (Standard License)","filename":"sky-lagoon-hero.webp","horizon_view":true}]', '{"sweep":[{"azimuth":205,"distance_m":21000,"horizon_angle":0.5244798790688437},{"azimuth":206,"distance_m":25000,"horizon_angle":0.535588605564513},{"azimuth":207,"distance_m":24000,"horizon_angle":0.4705495727604415},{"azimuth":208,"distance_m":24000,"horizon_angle":0.5077283946704263},{"azimuth":209,"distance_m":27000,"horizon_angle":0.5174750819962632},{"azimuth":210,"distance_m":27000,"horizon_angl