-- svodufoss-waterfall
INSERT INTO "public"."viewing_spots" ("id", "name", "slug", "lat", "lng", "region", "description", "parking_info", "terrain_notes", "has_services", "cell_coverage", "totality_duration_seconds", "totality_start", "sun_altitude", "sun_azimuth", "spot_type", "trail_distance_km", "trail_time_minutes", "difficulty", "elevation_gain_m", "trailhead_lat", "trailhead_lng", "photos", "horizon_check", "warnings", "nearby_poi", "observer_height_above_ground") VALUES ('svodufoss-waterfall', 'Svöðufoss Waterfall', 'svodufoss-waterfall', 64.876, -23.556, 'snaefellsnes', 'A photogenic 10-meter waterfall cascading over a stunning columnar basalt cliff on the northern side of the Snæfellsnes Peninsula. Located between Ólafsvík and Grundarfjörður with around two minutes of totality. The waterfall faces south, while the eclipse sun is to the west — meaning the basalt columns and cascade can serve as dramatic foreground without obstructing the sun itself.', 'Small pull-off area along the road. Approximately 10 cars. Easy to miss — look for a small sign.', 'Short walk from the road to the waterfall viewpoint. Flat to gently sloping terrain. The viewing area has open views to the west across farmland and toward the coast.', false, 'limited', 116, '2026-08-12 17:45:55+00', 25.1, 250.4, 'drive-up', null, null, null, null, null, null, '[{"alt":"Svodufoss waterfall with Snaefellsjokull glacier in the distance","credit":"Unsplash / Sitraka","is_hero":true,"license":"unsplash","filename":"svodufoss-waterfall-hero.webp","horizon_view":true}]', '{"sweep":[{"azimuth":205,"distance_m":650,"horizon_angle":7.421150621838291},{"azimuth":206,"distance_m":650,"horizon_angle":7.267232172892874},{"azimuth":207,"distance_m":650,"horizon_angle":6.941720586559335},{"azimuth":208,"distance_m":650,"horizon_angle":6.430863297051559},{"azimuth":209,"distance_m":650,"horizon_angle":5.659532375370585},{"azimuth":210,"distance_m":650,"horizon_angle":4.883640265677233},{"azimuth":211,"distance_m":650,"horizon_angle"