INSERT INTO "public"."viewing_spots" ("id", "name", "slug", "lat", "lng", "region", "description", "parking_info", "terrain_notes", "has_services", "cell_coverage", "totality_duration_seconds", "totality_start", "sun_altitude", "sun_azimuth", "spot_type", "trail_distance_km", "trail_time_minutes", "difficulty", "elevation_gain_m", "trailhead_lat", "trailhead_lng", "photos", "horizon_check", "warnings", "nearby_poi", "observer_height_above_ground") VALUES ('ytri-tunga-beach', 'Ytri Tunga Beach', 'ytri-tunga-beach', 64.8027829789199, -23.0803228516799, 'snaefellsnes', 'One of the best places in Iceland to see harbor seals up close — they regularly haul out on the rocks just offshore, especially in summer. Unlike most Icelandic beaches, Ytri Tunga has golden sand rather than black. Located on the southern coast of the Snæfellsnes Peninsula with a clear view west over Faxaflói bay. An eclipse with seals on the beach in the foreground would be a unique wildlife-meets-astronomy moment.', 'Small parking lot at the beach access point. Approximately 15 cars. Short walk to the beach.', 'Flat golden sand beach on the south coast. Open view W/SW over Faxaflói bay. Low terrain, no obstructions.', false, 'good', 105, '2026-08-12 17:46:30+00', 24.9, 251, 'drive-up', null, null, null, null, 64.8039490147231, -23.0804403794108, '[{"alt":"Seal colony beach at Ytri Tunga on Snaefellsnes peninsula","credit":"EclipseChase.is / Martin Herchl","is_hero":true,"license":"© Martin Herchl — All rights reserved","filename":"ytri-tunga-beach-hero.webp","horizon_view":true}]', '{"sweep":[{"azimuth":205,"distance_m":5500,"horizon_angle":0},{"azimuth":206,"distance_m":5500,"horizon_angle":0},{"azimuth":207,"distance_m":5500,"horizon_angle":0},{"azimuth":208,"distance_m":5500,"horizon_angle":0},{"azimuth":209,"distance_m":5500,"horizon_angle":0},{"azimuth":210,"distance_m":5500,"horizon_angle":0},{"azimuth":211,"distance_m":5500,"horizon_angle":0},{"azimuth":212,"distance_m":5500,"horizon_angle":0}